205	    let mut state = game_at_step(Step::Upkeep, P0);
206	    let pariah = named_creature(&mut state, &reg, "Tormented Pariah", P0);
207	
208	    assert_eq!(state.effective_power(pariah, &reg).unwrap(), 3);
