251	#[test]
252	fn mayor_of_avabruck_transforms_and_buffs_werewolves() {
253	    let reg = registry();
254	    let mut state = game_at_step(Step::Upkeep, P0);
255	    let mayor = named_creature(&mut state, &reg, "Mayor of Avabruck", P0);
256	    let other_wolf = named_creature(&mut state, &reg, "Reckless Waif", P0);
257	
258	    // Transform both
259	    trigger_upkeep(&mut state, &reg);
260	
261	    // Mayor is now Howlpack Alpha (3/3), gives other Werewolves/Wolves +1/+1
262	    assert!(state.get_object(mayor).unwrap().is_transformed);
263	    assert_eq!(state.effective_power(mayor, &reg).unwrap(), 3);
264	
