    let reg = registry();
    let mut state = game_at_step(Step::DeclareAttackers, P0);
    let gang = named_creature(&mut state, &reg, "Instigator Gang", P0);

    // Base power is 2.
    assert_eq!(state.effective_power(gang, &reg).unwrap(), 2);

