876	/// Resolve the top trigger from the stack.
877	/// Returns true if a trigger was resolved, false if the top of stack is not a trigger.
878	pub fn resolve_next_trigger(state: &mut GameState, registry: &CardRegistry) -> bool {
879	    // Check if the top of stack is a trigger.
880	    let is_trigger = state.stack.last()
881	        .map(|e| matches!(e, crate::state::StackEntry::Trigger(_)))
882	        .unwrap_or(false);
883	    if !is_trigger {
884	        return false;
885	    }
886	    let entry = state.stack.pop().expect("stack must have trigger entry");
887	    let trigger = match entry {
888	        crate::state::StackEntry::Trigger(t) => t,
889	        _ => unreachable!(),
